-- Requirements catalog imported from schema/shared_health_record_schema.csv.
-- This is a FHIR resource requirements catalog, not a replacement for the
-- operational registry, referral, and resource tables.
create table if not exists shr_profile_requirements (
  requirement_id       text primary key,
  domain               text not null,
  resource_type        text not null,
  element_path         text not null,
  cardinality          text not null,
  fhir_datatype        text not null,
  requirement          text not null check (requirement in ('Required', 'Recommended', 'Optional', 'Conditional')),
  purpose              text not null,
  terminology_guidance text,
  reference_targets    text[] not null default '{}',
  implementation_notes text,
  source_sha256        text not null check (source_sha256 ~ '^[0-9a-f]{64}$'),
  loaded_at            timestamptz not null default now()
);

create index if not exists shr_profile_requirements_resource_idx
  on shr_profile_requirements (resource_type, element_path);
create index if not exists shr_profile_requirements_domain_idx
  on shr_profile_requirements (domain, resource_type);

alter table shr_profile_requirements enable row level security;


on conflict (requirement_id) do nothing;
